"""Reassign HighQ Windows offers that were generated by the Nordica account.

Quote history shows quote['user']. An order made from that quote shows
approved_by. This pass rewrites only those two fields, and only when the
company is HighQ Windows and the address is Adrian at nordicaaluminum.
It is safe to run on every startup: a record already pointing at
erp@oraglass.us is left alone.
"""

import logging
import re

from storage import load_customers, load_orders, load_quotes, load_users, save_orders, save_quotes

logger = logging.getLogger('ora_glass.highq')

TARGET_EMAIL = 'erp@oraglass.us'
_ADRIAN = re.compile(r'^adrian@nordicaaluminum', re.IGNORECASE)


def _company_text(value):
    return re.sub(r'[^a-z0-9]+', ' ', str(value or '').casefold()).strip()


def _is_highq_name(value):
    text = _company_text(value)
    return text == 'highq windows' or text.startswith('highq windows ')


def _is_adrian(email):
    return bool(_ADRIAN.match(str(email or '').strip()))


def _target_email(users):
    """The stored login for erp@oraglass.us. None when that user has not been created."""
    exact = None
    for key in users or {}:
        if str(key).strip().casefold() == TARGET_EMAIL:
            if key == TARGET_EMAIL:
                return key
            exact = key
    return exact


def _highq_customer_ids(customers):
    found = set()
    for customer_id, customer in (customers or {}).items():
        if not isinstance(customer, dict):
            continue
        if _is_highq_name(customer.get('name')) or _is_highq_name(customer_id):
            found.add(customer_id)
    return found


def _is_highq_record(record, highq_ids):
    if _is_highq_name(record.get('company')):
        return True
    return record.get('customer_id') in highq_ids


def reassign_quote_owners():
    """Move HighQ offers generated by Adrian@nordicaaluminum* onto erp@oraglass.us.

    Returns {'quotes', 'orders', 'skipped'}. skipped is True when the target
    user does not exist and nothing was written.
    """
    target = _target_email(load_users())
    if not target:
        logger.warning(
            'HighQ quote owner fix skipped: user %s does not exist. No quotes or orders were changed.',
            TARGET_EMAIL,
        )
        return {'quotes': 0, 'orders': 0, 'skipped': True}

    highq_ids = _highq_customer_ids(load_customers())
    quotes = load_quotes()
    orders = load_orders()
    quote_ids = set()
    quote_changes = 0
    for quote in quotes:
        if not isinstance(quote, dict) or not _is_highq_record(quote, highq_ids):
            continue
        if _is_adrian(quote.get('user')):
            quote['user'] = target
            quote_changes += 1
        if str(quote.get('user') or '').strip().casefold() == target.casefold():
            if quote.get('id') is not None:
                quote_ids.add(quote.get('id'))

    order_changes = 0
    for order in orders:
        if not isinstance(order, dict):
            continue
        if order.get('quote_id') not in quote_ids:
            continue
        if not _is_adrian(order.get('approved_by')):
            continue
        order['approved_by'] = target
        order_changes += 1

    if quote_changes:
        save_quotes(quotes)
    if order_changes:
        save_orders(orders)
    logger.info(
        'HighQ quote owner fix: reassigned %s quote(s) and %s order(s) to %s.',
        quote_changes, order_changes, target,
    )
    return {'quotes': quote_changes, 'orders': order_changes, 'skipped': False}
